const {test}=require('node:test'),assert=require('node:assert/strict'),{verifyCompactAssets}=require('./verify-compact-assets.cjs');
const valid=()=>({page:'<script type="module" src="/assets/index.js?printRecovery=r1858"></script>',app:'PB1858resume pb1858PhotoState',mobile:'syncPrintActions',header:'syncPrintActions'});
test('production HTML can omit obsolete direct mobile scripts',()=>{const input=valid();assert(!input.page.includes('printActions=r1858'));assert(Object.values(verifyCompactAssets(input)).every(Boolean))});
for(const field of ['page','app','mobile','header'])test('stale '+field+' fails the publication check with diagnostics',()=>{const input=valid();input[field]='old content';assert.throws(()=>verifyCompactAssets(input),/mismatch:.*false/)});
test('a duplicate recovery queue cannot pass publication verification',()=>{const input=valid();input.app+=" className:'pb1854File'";assert.throws(()=>verifyCompactAssets(input),/noDuplicateQueue":false/)});
test('mobile scripts directly referenced by HTML still require a fresh cache version',()=>{const input=valid();input.page+='<script src="/photobridge-v904r100f40-mobile-polish.js?v=old"></script>';assert.throws(()=>verifyCompactAssets(input),/referencedVersions":false/);input.page=input.page.replace('v=old','v=old&printActions=r1858');assert(Object.values(verifyCompactAssets(input)).every(Boolean))});
